AND u.id IN (
    SELECT ur.user_id
    FROM user_role ur
    JOIN `role` r ON r.id = ur.role_id
    WHERE r.code = #{roleCode}
)

mapper.update:
UPDATE `user`
name = #{name}, password = #{password}, email = #{email}, phone = #{phone}, age = #{age}, gender = #{gender},
